INSERT INTO `new_mail_history` (`id`, `user_id`, `subject`, `message`, `created_at`, `updated_at`) VALUES
	(53, 526, 'Robert - adding you to VIP Room', 'Hi Robert,\r\n\r\nThanks for joining my Trade Signal Service. \r\n\r\nI noticed you tried to sign up for the $1 package for my Trade Signals.\r\n\r\nBut payment was not completed. Did you have some trouble on the website? let me know so I can help you solve it and get into the VIP room to start following my work. \r\n\r\nI\'ll also drop you a whatsapp message. \r\n\r\nRegards... Nasir', '2022-08-15 08:08:18', '2022-08-15 08:08:18'),
	(296, 769, 'Rickie- adding you to VIP Room', '<p>Hi Rickie,\r\n</p><p><br></p><p>\r\nThanks for joining my Trade Signal Service. </p><p>\r\n\r\nI noticed you tried to sign up for the $1 package for my Trade Signals.\r\n\r\nBut payment was not completed. </p><p><span style="font-size: 1rem;">Did you have some trouble on the website? </span></p><p><span style="font-size: 1rem;">Let me know so I can help you solve it and get into the VIP room to start following my work.</span></p><p><span style="font-size: 1rem;"><br></span></p><p><span style="font-size: 1rem;"> </span></p><p><span style="font-size: 1rem;">\r\n\r\n</span></p><p><span style="font-size: 1rem;">I\'ll also drop you a whatsapp message. </span></p><p><span style="font-size: 1rem;"><br></span></p><p><span style="font-size: 1rem;">\r\n\r\nRegards... Nasir</span><br></p>', '2022-11-22 17:46:06', '2022-11-22 17:46:06'),
	(39, 515, 'Rob test 1 FROM save', 'This message being saved Rob', '2022-08-10 06:42:31', '2022-08-10 06:42:31'),
	(22, 514, 'Thanks for joining Allen', 'Hi Allen,\r\n\r\nI noticed your want to join my trade signal for the monthly package. But your payment was not completed. Did you have any trouble completing the payment?\r\n\r\nLet me know so that I can help you solve this and get into the VIP room. \r\n\r\nI\'ll also drop you a message on the phone. \r\n\r\nRegards... Nasir', '2022-08-05 12:53:54', '2022-08-05 12:53:54'),
