INSERT INTO `trader_blogs` (`id`, `user_id`, `trader_category_id`, `name`, `sub_title`, `page_url`, `detail`, `image`, `videoLink`, `created_at`, `updated_at`) VALUES
	(54, 17, 4, 'Oil Coming Back to $20 Mark?', NULL, 'oil-coming-back-to-20-mark-', '<p>Check this chart out, its hourly scale, as I am looking for an entry point to get back into Oil as it recedes back towards low of $20. </p><p><br></p><p>Given the lacklustre results of the Opec and G20 meetings, it looks like the market is disappointed and oil is heading back towards $18-$20 range. </p><p><br></p><p>I\'d be looking to get into a position at $20. </p><p><br></p><p>CAUTION: Do be careful with increased volatility, especially if you are trading leveraged products.<br></p>', 'oil-coming-back-to-20-mark-2020-04-14-5e9547a68d4c4.png', NULL, '2020-04-14 05:18:30', '2020-04-14 05:18:30'),
	(55, 17, 5, 'Gold Breaching Resistance - Heading Towards $2000?', NULL, 'gold-breaching-resistance-heading-towards-2000-', '<p>\r\n\r\n</p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:16.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">In 2008-2011 we saw gold double.<span style="mso-spacerun:yes">&nbsp; </span>That would be the equivalent of seeing gold\r\ngo from around $1400 to $2800!</span></p>', 'gold-breaching-resistance-heading-towards-2000-2020-04-14-5e954cec83ff3.png', NULL, '2020-04-14 05:41:00', '2020-04-14 05:41:00'),
	(56, 17, 6, 'Markets Hit Resistance. Time to go back down.', NULL, 'markets-hit-resistance-time-to-go-back-down-', '<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Markets have rebounded well\r\n(temporarily), now testing the old support which is a strong resistance now. Get ready for a reversal.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"><br></span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Given the outlook, and that we </span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">havent</span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%"> seen\r\nthe ripple effects of the COVID-19 on the economies and corporate earnings yet,\r\nthe market should run out of steam and head back down. Possibly coinciding the\r\ntiming with corporate earnings, and further updates on COVID-19 damages.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%"><br></span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;font-weight:bold;mso-style-textfill-type:\r\nsolid;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:\r\nblack;mso-style-textfill-fill-alpha:100.0%">Look to short the markets back down\r\nto 18000 at least.</span></p>', 'markets-hit-resistance-time-to-go-back-down-2020-04-14-5e954faecbb15.png', NULL, '2020-04-14 05:52:46', '2020-04-14 05:52:46'),
	(58, 17, 4, 'Oil Weekly Analysis - last 29 years', NULL, 'oil-weekly-analysis-last-29-years', '<p>\r\n\r\n</p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">There is a clear pattern on crude over\r\nthe last 29 years. </span></p>\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">The falls are becoming less step creating\r\na descending triangle pattern.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"><br></span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Expect oil to bounce back up from the\r\nlows close to $30, since oil is not becoming obsolete anytime soon.</span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Upward price movement may be limited to\r\naround $60 until we see some dramatic market changes over the coming years.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"><br></span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">However could a severely collapsing\r\nmarket drag oil to close to $20?</span></p>', 'oil-weekly-analysis-last-29-years-2020-04-14-5e9568fc59b38.png', NULL, '2020-04-14 07:40:44', '2020-04-14 07:40:44'),
	(59, 17, 5, 'GOLD is a Strong Buy Now', NULL, 'gold-is-a-strong-buy-now', '<p>\r\n\r\n</p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">After many years GOLD has become a good\r\nbuy when it broker above 1350. with collapsing markets we should see gold hit\r\nnew record highs over the coming year.<br>\r\n<br>\r\nPost 2008 gold kept rising as the </span><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">marketings</span><span style="font-size:\r\n18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:\r\n+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"> found ground. Expect similar again.</span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Around $1550 might be a good entry point</span></p>', 'gold-is-a-strong-buy-now-2020-04-14-5e95696d21c15.jpg', NULL, '2020-04-14 07:42:37', '2020-04-14 07:42:37'),
	(60, 17, 6, 'Dow Jones Sharpest Decline... Ever', NULL, 'dow-jones-sharpest-decline-ever', '<p>\r\n\r\n</p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">S</span><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">harpest decline in 23 years, markets are\r\npoised for a </span><span style="font-size:18.0pt;font-family:Calibri;\r\nmso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;mso-bidi-font-family:\r\n+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:minor-fareast;\r\nmso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;mso-font-kerning:\r\n12.0pt;language:en-GB;mso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">a</span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">\r\nmajor collapse bigger than 2008.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%"><br></span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Monetary policy has little room for\r\nmanoeuvre as they left interest rates at extremely low.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"><br></span></p>\r\n\r\n\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">No real floor until around 12,000. But </span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">im</span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%"> sure\r\nthere will </span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:\r\nCalibri;mso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">eb</span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nmso-style-textfill-type:solid;mso-style-textfill-fill-themecolor:text1;\r\nmso-style-textfill-fill-color:black;mso-style-textfill-fill-alpha:100.0%">\r\nstimulus to stop it hitting such a low. However quite easily markets can fall\r\nto 18,000 with a bumpy ride down. </span></p>', 'dow-jones-sharpest-decline-ever-2020-04-14-5e956a0a7eb4d.jpg', NULL, '2020-04-14 07:45:14', '2020-04-14 07:45:14'),
	(61, 17, 4, 'Buying Oil at $20', NULL, 'buying-oil-at-20', '<p>I am about to trade Oil, at this beautiful breakout. </p><p>Rarely do I see such a perfect opportunity at such a low price for an important commodity like Oil. </p><p><br></p><p>I\'m trading May Call Options for this, expecting oil to hit around $30 per barrel. Follow my live trading on the subsequent updates I will be posting with Live video recordings of my positions. <br></p>', 'buying-oil-at-20-2020-04-14-5e956a8d154d2.jpg', NULL, '2020-04-14 07:47:25', '2020-04-14 07:47:25'),
	(62, 17, 4, 'Oil Trade Update', NULL, 'oil-trade-update', '<p>Oil has broken out as expected. <br></p><p>\r\n\r\n</p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">Oil could hit 24 by Friday 3</span><span style="font-size:18.0pt;font-family:Calibri;mso-ascii-font-family:Calibri;\r\nmso-fareast-font-family:+mn-ea;mso-bidi-font-family:+mn-cs;mso-ascii-theme-font:\r\nminor-latin;mso-fareast-theme-font:minor-fareast;mso-bidi-theme-font:minor-bidi;\r\ncolor:black;mso-color-index:1;mso-font-kerning:12.0pt;language:en-GB;\r\nvertical-align:super;mso-text-raise:30%;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">rd</span><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"> April, due </span></p>\r\n\r\n<p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">to the talks between USA, SAUDI and\r\nRUSSIA.</span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%"><br></span></p><p style="language:en-GB;margin-top:0pt;margin-bottom:0pt;margin-left:0in;\r\ntext-align:left;direction:ltr;unicode-bidi:embed;mso-line-break-override:none;\r\nword-break:normal;punctuation-wrap:hanging"><span style="font-size:18.0pt;\r\nfont-family:Calibri;mso-ascii-font-family:Calibri;mso-fareast-font-family:+mn-ea;\r\nmso-bidi-font-family:+mn-cs;mso-ascii-theme-font:minor-latin;mso-fareast-theme-font:\r\nminor-fareast;mso-bidi-theme-font:minor-bidi;color:black;mso-color-index:1;\r\nmso-font-kerning:12.0pt;language:en-GB;mso-style-textfill-type:solid;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-color:black;\r\nmso-style-textfill-fill-alpha:100.0%">I\'ll be ad